<script setup lang="ts">
import { computed, reactive, ref } from 'vue'
import { useMutation, useQuery, useQueryClient } from '@tanstack/vue-query'
import { ElMessage } from 'element-plus'
import { useRoute } from 'vue-router'
import { charactersApi, chaptersApi } from '@/api/endpoints/assets'
import { batchesApi } from '@/api/endpoints/v15'
import type { ChapterBatchResponse } from '@/api/types'
import EmptyState from '@/components/base/EmptyState.vue'
import ErrorState from '@/components/base/ErrorState.vue'
import LoadingState from '@/components/base/LoadingState.vue'
import ProblemAlert from '@/components/base/ProblemAlert.vue'

const route = useRoute(); const client = useQueryClient(); const projectId = computed(() => String(route.params.projectId ?? ''))
const key = computed(() => ['chapter-batches', projectId.value])
const query = useQuery({ queryKey: key, queryFn: () => batchesApi.list(projectId.value), refetchInterval: 5_000 })
const chapters = useQuery({ queryKey: computed(() => ['chapters', projectId.value]), queryFn: () => chaptersApi.list(projectId.value) })
const characters = useQuery({ queryKey: computed(() => ['characters', projectId.value]), queryFn: () => charactersApi.list(projectId.value) })
const selected = ref<ChapterBatchResponse>(); const gates = ref<Record<string, Awaited<ReturnType<typeof batchesApi.gates>>>>({})
const form = reactive({ viewpointCharacterId: '', instruction: '', chapterIds: [] as string[], gatedChapterIds: [] as string[] })
const create = useMutation({ mutationFn: () => batchesApi.create(projectId.value, form), onSuccess: async value => { selected.value = value; Object.assign(form, { instruction: '', chapterIds: [], gatedChapterIds: [] }); await refresh(); ElMessage.success('章节批次已启动') } })
const action = useMutation({ mutationFn: ({ id, type }: { id: string; type: 'pause' | 'resume' | 'cancel' }) => batchesApi[type](id), onSuccess: refresh })
const gateAction = useMutation({ mutationFn: ({ id, approve }: { id: string; approve: boolean }) => batchesApi.decideGate(id, approve), onSuccess: async value => { await loadGates(value.batchId); await refresh() } })
async function refresh(): Promise<void> { await client.invalidateQueries({ queryKey: key.value }) }
async function loadGates(batchId: string): Promise<void> { gates.value[batchId] = await batchesApi.gates(batchId) }
function toggleChapter(id: string, checked: boolean): void { form.chapterIds = checked ? [...form.chapterIds, id].slice(0, 3) : form.chapterIds.filter(x => x !== id); if (!checked) form.gatedChapterIds = form.gatedChapterIds.filter(x => x !== id) }
function toggleGate(id: string, checked: boolean): void { form.gatedChapterIds = checked ? [...form.gatedChapterIds, id] : form.gatedChapterIds.filter(x => x !== id) }
</script>
<template><main class="page-container"><header class="page-header"><div><p class="eyebrow">Long-form production</p><h1 tabindex="-1">连续写作</h1><p>选择 1–3 个现有章节串行运行。每章仍需审校和原子提交，重大剧情点会在启动该章前停住。</p></div></header><section class="v15-panel"><h2>新建章节批次</h2><ProblemAlert v-if="create.isError.value" :error="create.error.value"/><form class="sw-form" @submit.prevent="create.mutate()"><label class="form-field"><span>视角人物</span><select v-model="form.viewpointCharacterId" required><option value="" disabled>选择人物</option><option v-for="character in characters.data.value" :key="character.id" :value="character.id">{{ character.name }}</option></select></label><label class="form-field"><span>批次写作指令</span><textarea v-model="form.instruction" rows="4" maxlength="20000" required/></label><fieldset class="chapter-picker"><legend>章节（最多 3 章）</legend><label v-for="chapter in chapters.data.value" :key="chapter.id"><input type="checkbox" :checked="form.chapterIds.includes(chapter.id)" :disabled="!form.chapterIds.includes(chapter.id) && form.chapterIds.length >= 3" @change="toggleChapter(chapter.id, ($event.target as HTMLInputElement).checked)"/><span>第 {{ chapter.chapterNo }} 章 · {{ chapter.title }}</span><input type="checkbox" :checked="form.gatedChapterIds.includes(chapter.id)" :disabled="!form.chapterIds.includes(chapter.id)" aria-label="设为重大剧情门" @change="toggleGate(chapter.id, ($event.target as HTMLInputElement).checked)"/><small>剧情门</small></label></fieldset><button class="sw-button sw-button--primary" :disabled="form.chapterIds.length < 1 || create.isPending.value">启动批次</button></form></section><LoadingState v-if="query.isPending.value"/><ErrorState v-else-if="query.isError.value" :error="query.error.value" @retry="query.refetch()"/><EmptyState v-else-if="!query.data.value?.length" title="还没有章节批次" description="选择章节和视角人物开始串行生产。"/><section v-else class="asset-list"><article v-for="batch in query.data.value" :key="batch.id" class="asset-card"><div class="asset-card-heading"><div><span class="asset-type">{{ batch.items.length }} 章 · 已完成 {{ batch.currentIndex }}</span><h2>{{ batch.instruction }}</h2></div><span class="status-pill">{{ batch.status }}</span></div><ol class="batch-items"><li v-for="item in batch.items" :key="item.id"><span>第 {{ item.sequenceNo }} 项</span><RouterLink :to="`/projects/${projectId}/chapters/${item.chapterId}${item.workflowRunId ? `/workflows/${item.workflowRunId}` : ''}`">{{ item.chapterId }}</RouterLink><span class="status-pill">{{ item.status }}</span></li></ol><div class="asset-actions"><button v-if="batch.status === 'RUNNING'" @click="action.mutate({ id: batch.id, type: 'pause' })">暂停后续章节</button><button v-if="batch.status === 'PAUSED'" @click="action.mutate({ id: batch.id, type: 'resume' })">恢复</button><button v-if="!['COMPLETED','CANCELLED'].includes(batch.status)" @click="action.mutate({ id: batch.id, type: 'cancel' })">取消</button><button @click="loadGates(batch.id)">查看剧情门</button></div><div v-if="gates[batch.id]?.length" class="gate-list"><article v-for="gate in gates[batch.id]" :key="gate.id"><div><strong>{{ gate.title }}</strong><p>{{ gate.rationale }}</p></div><span class="status-pill">{{ gate.status }}</span><div v-if="gate.status === 'PENDING'" class="asset-actions"><button @click="gateAction.mutate({ id: gate.id, approve: true })">批准并继续</button><button @click="gateAction.mutate({ id: gate.id, approve: false })">拒绝并终止</button></div></article></div></article></section></main></template>
